extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var code := source_of("res://enemy.gd")
	if not check("file_exists", not code.is_empty(), "Lo script res://enemy.gd deve esistere"):
		return

	var phys_idx := code.find("func _physics_process")
	if phys_idx != -1:
		var next_func := code.find("func ", phys_idx + 15)
		var phys_code := code.substr(phys_idx, next_func - phys_idx if next_func != -1 else -1)
		var calls_in_physics := phys_code.contains("_check_for_player") or phys_code.contains("_check_lost_player")
		check("no_checks_in_physics", not calls_in_physics, "La funzione _physics_process() non deve più chiamare _check_for_player() o _check_lost_player()")

	var timer_idx := code.find("func _on_path_timer_timeout")
	if timer_idx != -1:
		var next_func := code.find("func ", timer_idx + 20)
		var timer_code := code.substr(timer_idx, next_func - timer_idx if next_func != -1 else -1)
		var calls_in_timer := timer_code.contains("_check_for_player") and timer_code.contains("_check_lost_player")
		check("checks_in_timer", calls_in_timer, "La funzione _on_path_timer_timeout() deve chiamare _check_for_player() e _check_lost_player()")

	var enemy_scene := load("res://enemy.tscn") as PackedScene
	if not check("scene_exists", enemy_scene != null, "La scena res://enemy.tscn deve caricarsi correttamente"):
		return

	var enemy := enemy_scene.instantiate() as CharacterBody2D
	get_tree().root.add_child(enemy)
	await wait_frames(2)

	var player_body := CharacterBody2D.new()
	player_body.name = "Player"
	var col_shape := CollisionShape2D.new()
	var rect_shape := RectangleShape2D.new()
	rect_shape.size = Vector2(32.0, 32.0)
	col_shape.shape = rect_shape
	player_body.add_child(col_shape)
	player_body.position = Vector2(50.0, 0.0)
	get_tree().root.add_child(player_body)
	await wait_frames(2)

	enemy.set("player", player_body)

	call_if_exists(enemy, "_on_path_timer_timeout", [])
	var state_val = get_prop(enemy, "current_state", -1)
	check("state_chase", int(state_val) == 1, "Quando scatta il timer e il giocatore è in vista, il nemico deve passare allo stato CHASE (1) (stato misurato: %s)" % str(state_val))

	player_body.position = Vector2(600.0, 0.0)
	call_if_exists(enemy, "_on_path_timer_timeout", [])
	var state_after = get_prop(enemy, "current_state", -1)
	check("state_return", int(state_after) == 2, "Quando scatta il timer e il nemico perde di vista il giocatore, deve passare allo stato RETURN (2) (stato misurato: %s)" % str(state_after))

	enemy.queue_free()
	player_body.queue_free()
	await wait_frames(2)

