		if health_component != null:
			health_component.take_damage(hitbox.damage)

extends Node2D

@onready var ground: TileMapLayer = $Ground
@onready var walls: TileMapLayer = $Walls
@onready var decoration: TileMapLayer = $Decoration
@onready var camera: Camera2D = $Player/Camera2D


func _ready() -> void:
	for x in range(50):
		for y in range(35):
			ground.set_cell(Vector2i(x, y), 0, Vector2i(2, 0))

	for x in range(50):
		for y in range(35):
			if (x == 0 or x == 49 or y == 0 or y == 34) and not (x == 25 and y == 34):
				walls.set_cell(Vector2i(x, y), 0, Vector2i(3, 0))
			else:
				walls.set_cell(Vector2i(x, y), -1)

	decoration.set_cell(Vector2i(3, 3), 0, Vector2i(2, 1))

	setup_camera_limits()


func setup_camera_limits() -> void:
	var used_rect: Rect2i = ground.get_used_rect()
	var tile_size: Vector2i = ground.tile_set.tile_size

	camera.limit_left = used_rect.position.x * tile_size.x
	camera.limit_top = used_rect.position.y * tile_size.y
	camera.limit_right = used_rect.end.x * tile_size.x
	camera.limit_bottom = used_rect.end.y * tile_size.y
	camera.reset_smoothing()

extends CharacterBody2D

enum State { PATROL, CHASE, RETURN }

@export var speed: float = 70.0
@export var chase_speed: float = 110.0
@export var vision_distance: float = 180.0
@export var waypoints: Array[Node2D] = []

var current_state: State = State.PATROL
var current_waypoint_index: int = 0
var player: Node2D = null

@onready var ray_cast: RayCast2D = $RayCast2D
@onready var health: Health = $Health
@onready var navigation_agent: NavigationAgent2D = $NavigationAgent2D
@onready var path_timer: Timer = $PathTimer


func _ready() -> void:
	if health != null:
		health.died.connect(_on_died)

	path_timer.timeout.connect(_on_path_timer_timeout)

	var current_scene := get_tree().current_scene
	if current_scene != null:
		var found_player := current_scene.find_child("Player", true, false)
		if found_player is Node2D:
			player = found_player as Node2D

	_setup_navigation.call_deferred()


func _setup_navigation() -> void:
	await get_tree().physics_frame
	_update_navigation_target()


func _physics_process(delta: float) -> void:
	match current_state:
		State.PATROL:
			_process_patrol()
			_check_for_player()
		State.CHASE:
			_process_chase()
			_check_lost_player()
		State.RETURN:
			_process_return()
			_check_for_player()

	move_and_slide()


func _process_patrol() -> void:
	if waypoints.is_empty():
		velocity = Vector2.ZERO
		return

	var target: Node2D = waypoints[current_waypoint_index]
	if target == null:
		return

	if global_position.distance_to(target.global_position) < 8.0:
		current_waypoint_index = (current_waypoint_index + 1) % waypoints.size()
		target = waypoints[current_waypoint_index]
		if target == null:
			return

	var direction := global_position.direction_to(target.global_position)
	velocity = direction * speed


func _process_chase() -> void:
	if player == null:
		velocity = Vector2.ZERO
		return
	if navigation_agent.is_navigation_finished():
		velocity = Vector2.ZERO
		return
	var next_position: Vector2 = navigation_agent.get_next_path_position()
	var direction := global_position.direction_to(next_position)
	velocity = direction * chase_speed


func _process_return() -> void:
	if waypoints.is_empty():
		current_state = State.PATROL
		return

	var target: Node2D = waypoints[current_waypoint_index]
	if target == null:
		return

	if navigation_agent.is_navigation_finished() or global_position.distance_to(target.global_position) < 8.0:
		current_state = State.PATROL
		velocity = Vector2.ZERO
		return

	var next_position: Vector2 = navigation_agent.get_next_path_position()
	var direction := global_position.direction_to(next_position)
	velocity = direction * speed


func _update_navigation_target() -> void:
	match current_state:
		State.CHASE:
			if player != null:
				navigation_agent.target_position = player.global_position
		State.RETURN:
			if not waypoints.is_empty() and waypoints[current_waypoint_index] != null:
				navigation_agent.target_position = waypoints[current_waypoint_index].global_position


func _on_path_timer_timeout() -> void:
	if current_state == State.CHASE or current_state == State.RETURN:
		_update_navigation_target()


func _can_see_player() -> bool:
	if player == null:
		return false

	if global_position.distance_to(player.global_position) > vision_distance:
		return false

	ray_cast.target_position = ray_cast.to_local(player.global_position)
	ray_cast.force_raycast_update()

	if ray_cast.is_colliding():
		var collider := ray_cast.get_collider()
		return collider == player

	return false


func _check_for_player() -> void:
	if _can_see_player():
		current_state = State.CHASE
		_update_navigation_target()


func _check_lost_player() -> void:
	if not _can_see_player():
		current_state = State.RETURN
		_update_navigation_target()


func _on_died() -> void:
	queue_free()

extends Area2D

signal pressed
signal released

@export var is_pressed: bool = false

var _bodies_on_plate: int = 0


func _ready() -> void:
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)
	_update_visual()


func _on_body_entered(body: Node2D) -> void:
	if body is CharacterBody2D or body is RigidBody2D:
		_bodies_on_plate += 1
		if not is_pressed:
			is_pressed = true
			_update_visual()
			pressed.emit()


func _on_body_exited(body: Node2D) -> void:
	if body is CharacterBody2D or body is RigidBody2D:
		_bodies_on_plate = maxi(0, _bodies_on_plate - 1)
		if _bodies_on_plate == 0 and is_pressed:
			is_pressed = false
			_update_visual()
			released.emit()


func _update_visual() -> void:
	if is_pressed:
		modulate = Color(0.4, 1.0, 0.4)
		scale = Vector2(0.9, 0.9)
	else:
		modulate = Color(0.8, 0.8, 0.8)
		scale = Vector2(1.0, 1.0)

extends Node

const SAVE_FILE_PATH: String = "user://save_game.json"


func save_game(player: CharacterBody2D, level_node: Node) -> void:
	var save_data: Dictionary = {
		"player": {
			"pos_x": player.global_position.x if player != null else 0.0,
			"pos_y": player.global_position.y if player != null else 0.0,
			"keys": int(player.get("keys")) if player != null and player.get("keys") != null else 0
		},
		"world_objects": {}
	}

	if level_node != null:
		for node in level_node.get_children():
			if node.has_method("get_save_data"):
				var node_path: String = str(node.get_path())
				save_data["world_objects"][node_path] = node.get_save_data()

	var file := FileAccess.open(SAVE_FILE_PATH, FileAccess.WRITE)
	if file != null:
		var json_string: String = JSON.stringify(save_data, "\t")
		file.store_string(json_string)
		file.close()


func load_game(player: CharacterBody2D, level_node: Node) -> void:
	if not FileAccess.file_exists(SAVE_FILE_PATH):
		return

	var file := FileAccess.open(SAVE_FILE_PATH, FileAccess.READ)
	if file == null:
		return

	var json_text: String = file.get_as_text()
	file.close()

	var json := JSON.new()
	if json.parse(json_text) != OK:
		return

	if not json.data is Dictionary:
		return

	var save_data: Dictionary = json.data

	if save_data.has("player") and player != null:
		var p_data: Dictionary = save_data["player"]
		var px: float = float(p_data.get("pos_x", player.global_position.x))
		var py: float = float(p_data.get("pos_y", player.global_position.y))
		player.global_position = Vector2(px, py)
		if player.get("keys") != null:
			player.set("keys", int(p_data.get("keys", 0)))

	if save_data.has("world_objects") and level_node != null:
		var objects_data: Dictionary = save_data["world_objects"]
		for path_key in objects_data:
			var target_node: Node = level_node.get_node_or_null(NodePath(path_key))
			if target_node == null:
				var parts: PackedStringArray = str(path_key).split("/")
				if parts.size() > 0:
					target_node = level_node.get_node_or_null(parts[parts.size() - 1])
			if target_node != null and target_node.has_method("load_save_data"):
				target_node.load_save_data(objects_data[path_key])

extends CharacterBody2D

@export var max_speed: float = 200.0
@export var acceleration: float = 1200.0
@export var friction: float = 1000.0
@export var sprint_multiplier: float = 1.5
@export var keys: int = 0


func _physics_process(delta: float) -> void:
	var input_direction := get_input_direction()
	update_velocity(input_direction, delta)
	move_and_slide()


func get_input_direction() -> Vector2:
	return Input.get_vector("move_left", "move_right", "move_up", "move_down")


func update_velocity(direction: Vector2, delta: float) -> void:
	if direction != Vector2.ZERO:
		var current_max_speed: float = max_speed
		if Input.is_action_pressed("sprint"):
			current_max_speed *= sprint_multiplier
		var target_velocity: Vector2 = direction * current_max_speed
		velocity = velocity.move_toward(target_velocity, acceleration * delta)
	else:
		velocity = velocity.move_toward(Vector2.ZERO, friction * delta)


func collect(item_type: String, amount: int) -> void:
	if item_type == "key":
		keys += amount


func get_save_data() -> Dictionary:
	return {
		"pos_x": global_position.x,
		"pos_y": global_position.y,
		"keys": keys
	}


func load_save_data(data: Dictionary) -> void:
	global_position = Vector2(float(data.get("pos_x", global_position.x)), float(data.get("pos_y", global_position.y)))
	keys = int(data.get("keys", keys))

extends StaticBody2D

signal opened
signal closed

@export var requires_key: bool = false
@export var is_open: bool = false

@onready var collision_shape: CollisionShape2D = $CollisionShape2D
@onready var interaction_area: Area2D = $InteractionArea


func _ready() -> void:
	_update_appearance()


func open() -> void:
	if is_open:
		return
	is_open = true
	if collision_shape != null:
		collision_shape.set_deferred("disabled", true)
	_update_appearance()
	opened.emit()


func close() -> void:
	if not is_open:
		return
	is_open = false
	if collision_shape != null:
		collision_shape.set_deferred("disabled", false)
	_update_appearance()
	closed.emit()


func _update_appearance() -> void:
	if is_open:
		modulate.a = 0.3
	else:
		modulate.a = 1.0


func get_save_data() -> Dictionary:
	return {
		"is_open": is_open
	}


func load_save_data(data: Dictionary) -> void:
	if data.get("is_open", false):
		open()
	else:
		close()

